const crypto = require('crypto');

// ----- scripts/lib/webhook-parser.js -----
/**
 * Meta WhatsApp Cloud API webhook payload parser.
 *
 * CANONICAL SOURCE. Unit-tested (tests/webhook/parser.test.js) and injected
 * into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * Payload shape verified against official documentation on 2026-09-09:
 *   https://developers.facebook.com/docs/whatsapp/cloud-api/webhooks/components
 *
 * A single webhook POST can legitimately contain MULTIPLE entries, each with
 * multiple changes, each with multiple messages and/or statuses. Flattening
 * that correctly matters: a naive `body.entry[0].changes[0].value.messages[0]`
 * silently drops messages under load, which looks exactly like "we lost a
 * customer's message".
 *
 * This parser NEVER throws. Malformed input produces `ok:false` plus a reason,
 * because a parser exception inside a webhook handler turns into a non-200
 * response, which makes Meta retry, which amplifies the failure.
 */


/** Message types this system explicitly understands. */
const SUPPORTED_MESSAGE_TYPES = [
  'text',
  'image',
  'audio',
  'video',
  'document',
  'sticker',
  'location',
  'contacts',
  'interactive',
  'button',
  'reaction',
  'order',
  'system',
];

/** Types for which we can extract human-readable text for the Sheets preview. */
const TEXT_BEARING_TYPES = ['text', 'button', 'interactive', 'reaction'];

const EVENT_KIND = {
  MESSAGE: 'message',
  STATUS: 'status',
  ERROR: 'error',
  UNKNOWN: 'unknown',
};

/**
 * Extract a short human-readable preview for the `last_message` column.
 * Media messages have no text, so we synthesize a stable placeholder rather
 * than writing "undefined" into a spreadsheet a manager will read.
 *
 * @returns {{text: string|null, preview: string, has_text: boolean}}
 */
function extractMessageText(message) {
  if (!message || typeof message !== 'object') {
    return { text: null, preview: '[unparseable message]', has_text: false };
  }

  const type = message.type;

  if (type === 'text' && message.text && typeof message.text.body === 'string') {
    return { text: message.text.body, preview: message.text.body, has_text: true };
  }

  // Quick-reply / CTA button taps.
  if (type === 'button' && message.button) {
    const t = message.button.text || message.button.payload || '';
    return { text: t || null, preview: t ? '[button] ' + t : '[button]', has_text: !!t };
  }

  // Interactive replies: list_reply / button_reply.
  if (type === 'interactive' && message.interactive) {
    const i = message.interactive;
    const reply = i.button_reply || i.list_reply || null;
    if (reply) {
      const t = reply.title || reply.id || '';
      return { text: t || null, preview: t ? '[interactive] ' + t : '[interactive]', has_text: !!t };
    }
    return { text: null, preview: '[interactive]', has_text: false };
  }

  if (type === 'reaction' && message.reaction) {
    const emoji = message.reaction.emoji || '';
    return { text: emoji || null, preview: '[reaction] ' + emoji, has_text: !!emoji };
  }

  // Media types may carry an optional caption.
  const mediaTypes = ['image', 'video', 'document', 'audio', 'sticker'];
  if (mediaTypes.indexOf(type) !== -1) {
    const media = message[type] || {};
    const caption = typeof media.caption === 'string' ? media.caption : null;
    const filename = typeof media.filename === 'string' ? media.filename : null;
    let preview = '[' + type + ']';
    if (filename) preview += ' ' + filename;
    if (caption) preview += ' ' + caption;
    return { text: caption, preview, has_text: !!caption };
  }

  if (type === 'location' && message.location) {
    const loc = message.location;
    const label = loc.name || loc.address || '';
    const coords =
      loc.latitude !== undefined && loc.longitude !== undefined
        ? loc.latitude + ',' + loc.longitude
        : '';
    return {
      text: null,
      preview: '[location] ' + (label || coords),
      has_text: false,
    };
  }

  if (type === 'contacts') {
    const n = Array.isArray(message.contacts) ? message.contacts.length : 0;
    return { text: null, preview: '[contacts x' + n + ']', has_text: false };
  }

  if (type === 'order') {
    return { text: null, preview: '[order]', has_text: false };
  }

  if (type === 'system' && message.system) {
    const body = message.system.body || '';
    return { text: body || null, preview: '[system] ' + body, has_text: !!body };
  }

  // Unknown/unsupported type — preserve the type name for debugging.
  return {
    text: null,
    preview: '[' + (type || 'unknown') + ']',
    has_text: false,
  };
}

/**
 * Convert Meta's Unix-seconds timestamp string to an ISO-8601 UTC string.
 * Returns null on garbage rather than "Invalid Date", which would poison
 * every downstream date comparison.
 */
function metaTimestampToIso(ts) {
  if (ts === undefined || ts === null || String(ts).trim() === '') return null;
  const seconds = Number(String(ts).trim());
  if (!isFinite(seconds) || seconds <= 0) return null;
  const d = new Date(seconds * 1000);
  if (isNaN(d.getTime())) return null;
  return d.toISOString();
}

/**
 * Parse a full webhook POST body into a flat list of normalized events.
 *
 * @param {object} body  Parsed JSON body of the webhook request.
 * @returns {{
 *   ok: boolean,
 *   reason: string|null,
 *   object: string|null,
 *   events: Array<object>,
 *   counts: {messages: number, statuses: number, errors: number, unknown: number}
 * }}
 */
function parseWebhook(body) {
  const out = {
    ok: false,
    reason: null,
    object: null,
    events: [],
    counts: { messages: 0, statuses: 0, errors: 0, unknown: 0 },
  };

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    out.reason = 'BODY_NOT_OBJECT';
    return out;
  }

  out.object = typeof body.object === 'string' ? body.object : null;

  // Meta always sets object='whatsapp_business_account' for WABA webhooks.
  // We accept but flag anything else instead of hard-failing, so a
  // misconfigured subscription is visible in the audit log.
  if (out.object !== 'whatsapp_business_account') {
    out.reason = 'UNEXPECTED_OBJECT_TYPE';
  }

  if (!Array.isArray(body.entry)) {
    out.reason = out.reason || 'MISSING_ENTRY_ARRAY';
    return out;
  }

  for (const entry of body.entry) {
    if (!entry || typeof entry !== 'object') continue;
    const wabaId = entry.id !== undefined ? String(entry.id) : null;
    const changes = Array.isArray(entry.changes) ? entry.changes : [];

    for (const change of changes) {
      if (!change || typeof change !== 'object') continue;
      const field = change.field !== undefined ? String(change.field) : null;
      const value = change.value && typeof change.value === 'object' ? change.value : {};
      const metadata = value.metadata && typeof value.metadata === 'object' ? value.metadata : {};

      // The business phone number that received the event. Critical for
      // multi-number WABAs: routing must be scoped per business number.
      const businessPhoneNumberId =
        metadata.phone_number_id !== undefined ? String(metadata.phone_number_id) : null;
      const businessDisplayPhone =
        metadata.display_phone_number !== undefined
          ? String(metadata.display_phone_number)
          : null;

      // contacts[] carries the customer's WhatsApp profile name, keyed by wa_id.
      const contactsByWaId = {};
      if (Array.isArray(value.contacts)) {
        for (const c of value.contacts) {
          if (c && c.wa_id !== undefined) {
            contactsByWaId[String(c.wa_id)] =
              c.profile && typeof c.profile.name === 'string' ? c.profile.name : null;
          }
        }
      }

      const base = {
        waba_id: wabaId,
        field,
        business_phone_number_id: businessPhoneNumberId,
        business_display_phone_number: businessDisplayPhone,
      };

      // ---- Inbound customer messages ----
      if (Array.isArray(value.messages)) {
        for (const m of value.messages) {
          if (!m || typeof m !== 'object') {
            out.counts.unknown += 1;
            out.events.push(Object.assign({}, base, {
              kind: EVENT_KIND.UNKNOWN,
              reason: 'MESSAGE_NOT_OBJECT',
            }));
            continue;
          }
          const type = m.type !== undefined ? String(m.type) : null;
          const supported = SUPPORTED_MESSAGE_TYPES.indexOf(type) !== -1;
          const textInfo = extractMessageText(m);
          const customerPhone = m.from !== undefined ? String(m.from) : null;

          out.counts.messages += 1;
          out.events.push(Object.assign({}, base, {
            kind: EVENT_KIND.MESSAGE,
            direction: 'inbound',
            message_id: m.id !== undefined ? String(m.id) : null,
            customer_phone: customerPhone,
            customer_name: customerPhone ? contactsByWaId[customerPhone] || null : null,
            message_type: type,
            supported,
            processing_status: supported ? 'parsed' : 'unsupported',
            text: textInfo.text,
            preview: textInfo.preview,
            has_text: textInfo.has_text,
            timestamp_unix: m.timestamp !== undefined ? String(m.timestamp) : null,
            timestamp_iso: metaTimestampToIso(m.timestamp),
            // Reply-to context, when the customer replies to a specific message.
            context_message_id: m.context && m.context.id ? String(m.context.id) : null,
            // Referral data present when the user arrived via a Click-to-WhatsApp ad.
            has_referral: !!m.referral,
            // Media id retained so the file can be fetched later if needed.
            media_id:
              m[type] && typeof m[type] === 'object' && m[type].id ? String(m[type].id) : null,
            mime_type:
              m[type] && typeof m[type] === 'object' && m[type].mime_type
                ? String(m[type].mime_type)
                : null,
            errors: Array.isArray(m.errors) ? m.errors : null,
          }));
        }
      }

      // ---- Outbound message status callbacks ----
      if (Array.isArray(value.statuses)) {
        for (const s of value.statuses) {
          if (!s || typeof s !== 'object') {
            out.counts.unknown += 1;
            out.events.push(Object.assign({}, base, {
              kind: EVENT_KIND.UNKNOWN,
              reason: 'STATUS_NOT_OBJECT',
            }));
            continue;
          }
          out.counts.statuses += 1;
          out.events.push(Object.assign({}, base, {
            kind: EVENT_KIND.STATUS,
            direction: 'outbound',
            // NOTE: this id refers to a message WE sent, so it matches a
            // previously stored outbound message_id.
            message_id: s.id !== undefined ? String(s.id) : null,
            status: s.status !== undefined ? String(s.status).toUpperCase() : null,
            recipient_phone: s.recipient_id !== undefined ? String(s.recipient_id) : null,
            timestamp_unix: s.timestamp !== undefined ? String(s.timestamp) : null,
            timestamp_iso: metaTimestampToIso(s.timestamp),
            conversation_id_meta:
              s.conversation && s.conversation.id ? String(s.conversation.id) : null,
            pricing_category:
              s.pricing && s.pricing.category ? String(s.pricing.category) : null,
            billable: s.pricing && s.pricing.billable !== undefined ? !!s.pricing.billable : null,
            errors: Array.isArray(s.errors) ? s.errors : null,
          }));
        }
      }

      // ---- Account-level errors delivered on the webhook ----
      if (Array.isArray(value.errors) && value.errors.length > 0) {
        for (const e of value.errors) {
          out.counts.errors += 1;
          out.events.push(Object.assign({}, base, {
            kind: EVENT_KIND.ERROR,
            error_code: e && e.code !== undefined ? String(e.code) : null,
            error_title: e && e.title ? String(e.title) : null,
            error_message: e && e.message ? String(e.message) : null,
          }));
        }
      }

      // A change with none of the above is a subscription field we don't
      // handle yet (e.g. account_update, template status). Record it.
      const producedSomething =
        (Array.isArray(value.messages) && value.messages.length > 0) ||
        (Array.isArray(value.statuses) && value.statuses.length > 0) ||
        (Array.isArray(value.errors) && value.errors.length > 0);

      if (!producedSomething) {
        out.counts.unknown += 1;
        out.events.push(Object.assign({}, base, {
          kind: EVENT_KIND.UNKNOWN,
          reason: 'NO_RECOGNISED_PAYLOAD',
          raw_value_keys: Object.keys(value),
        }));
      }
    }
  }

  // ok=true means "structurally parseable", independent of whether the
  // contents were all recognised.
  out.ok = out.reason === null || out.reason === 'UNEXPECTED_OBJECT_TYPE';
  return out;
}

// ----- scripts/lib/phone.js -----
/**
 * Phone number normalization to E.164.
 *
 * CANONICAL SOURCE. This file is unit-tested (tests/conversations/phone.test.js)
 * and injected verbatim into n8n Code nodes by scripts/setup/build-workflows.js.
 * Do not fork this logic inside a workflow — edit here and re-run the build.
 *
 * Storage rule: phone numbers are stored as E.164 WITHOUT the leading '+'
 * (digits only), matching the format Meta uses for `wa_id` / `from`.
 * The '+' form and the wa.me link are derived, never stored separately.
 *
 * Normalization rules (docs/ARCHITECTURE.md "Phone Number Normalization"):
 *   1. Strip all formatting: spaces, '-', '(', ')', '.', non-breaking spaces,
 *      and Arabic-Indic digits are transliterated to ASCII.
 *   2. '00' international prefix  -> dropped (00962... -> 962...)
 *   3. Leading '+'                -> dropped (+962... -> 962...)
 *   4. Leading '0' national form  -> '0' replaced with defaultCountryCode
 *                                    (0791234567 -> 962791234567)
 *   5. Already-E.164 digits       -> passed through unchanged
 *   6. Anything else is flagged AMBIGUOUS rather than silently rewritten.
 *
 * The function NEVER throws. Callers branch on `ok`.
 */


/** E.164 permits at most 15 digits; ITU minimum in practice is ~7 (+ country code). */
const E164_MAX_DIGITS = 15;
const E164_MIN_DIGITS = 8;

/** Arabic-Indic (٠-٩) and Eastern Arabic-Indic (۰-۹) digit transliteration. */
const ARABIC_DIGIT_MAP = {
  '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
  '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
  '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
  '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
};

/**
 * Country-specific national-number length checks. Used ONLY to detect
 * ambiguity, never to rewrite a number. Extend as more markets are added.
 * `nsnLengths` = valid lengths of the national significant number
 * (i.e. what follows the country code).
 */
const COUNTRY_RULES = {
  // Jordan: mobile NSN is 9 digits beginning with 7 (77/78/79 today).
  '962': { nsnLengths: [9], mobilePrefixes: ['7'], name: 'Jordan' },
};

function transliterateDigits(str) {
  let out = '';
  for (const ch of str) {
    out += Object.prototype.hasOwnProperty.call(ARABIC_DIGIT_MAP, ch)
      ? ARABIC_DIGIT_MAP[ch]
      : ch;
  }
  return out;
}

/**
 * @param {string} raw                 Phone number in any common format.
 * @param {object} [opts]
 * @param {string} [opts.defaultCountryCode='962']  Country code (no '+') used to
 *                                    expand national '0...' forms.
 * @returns {{
 *   ok: boolean,
 *   e164: string|null,          // digits only, no '+', e.g. '962791234567'
 *   e164Plus: string|null,      // '+962791234567'
 *   waLink: string|null,        // 'https://wa.me/962791234567'
 *   input: string,
 *   applied: string[],          // transformations applied, for audit
 *   ambiguous: boolean,
 *   reason: string|null         // machine-readable code when !ok or ambiguous
 * }}
 */
function normalizePhone(raw, opts) {
  const options = opts || {};
  const defaultCountryCode = String(
    options.defaultCountryCode || '962'
  ).replace(/\D/g, '');

  const result = {
    ok: false,
    e164: null,
    e164Plus: null,
    waLink: null,
    input: raw === undefined || raw === null ? '' : String(raw),
    applied: [],
    ambiguous: false,
    reason: null,
  };

  if (raw === undefined || raw === null || String(raw).trim() === '') {
    result.reason = 'EMPTY_INPUT';
    return result;
  }

  let s = transliterateDigits(String(raw).trim());
  if (s !== String(raw).trim()) result.applied.push('transliterated_arabic_digits');

  // Reject clearly non-numeric input (letters imply this isn't a phone number).
  if (/[A-Za-z]/.test(s)) {
    result.reason = 'CONTAINS_LETTERS';
    return result;
  }

  const hadPlus = s.startsWith('+');
  // Strip every character that isn't a digit (spaces, -, (), ., etc.).
  const digitsOnly = s.replace(/\D/g, '');
  if (digitsOnly.length !== s.length) result.applied.push('stripped_formatting');

  if (digitsOnly === '') {
    result.reason = 'NO_DIGITS';
    return result;
  }

  let e164 = digitsOnly;

  if (hadPlus) {
    // '+CC...' is already E.164; nothing to infer.
    result.applied.push('stripped_plus');
  } else if (e164.startsWith('00')) {
    // '00' is the international access prefix in most of the world.
    e164 = e164.slice(2);
    result.applied.push('stripped_00_idd_prefix');
  } else if (e164.startsWith('0')) {
    // National (trunk) format: replace the trunk '0' with the country code.
    e164 = defaultCountryCode + e164.slice(1);
    result.applied.push('national_to_e164:' + defaultCountryCode);
  }

  // Length sanity checks against E.164 bounds.
  if (e164.length > E164_MAX_DIGITS) {
    result.reason = 'TOO_LONG';
    result.e164 = null;
    return result;
  }
  if (e164.length < E164_MIN_DIGITS) {
    result.reason = 'TOO_SHORT';
    return result;
  }

  // Ambiguity detection — flag, don't rewrite.
  const rule = COUNTRY_RULES[defaultCountryCode];
  if (rule && !hadPlus && !digitsOnly.startsWith('00') && !digitsOnly.startsWith('0')) {
    const startsWithCountryCode = e164.startsWith(defaultCountryCode);
    if (!startsWithCountryCode) {
      const looksLikeBareNsn =
        rule.nsnLengths.indexOf(e164.length) !== -1 &&
        rule.mobilePrefixes.some((p) => e164.startsWith(p));
      if (looksLikeBareNsn) {
        // e.g. '791234567' — probably Jordanian without the trunk 0, but we
        // will not guess. Surface it and let the caller decide.
        result.ambiguous = true;
        result.reason = 'AMBIGUOUS_MISSING_COUNTRY_CODE';
      } else {
        // Some other country's E.164 number — legitimate, pass through.
        result.applied.push('assumed_foreign_e164');
      }
    }
  }

  result.ok = true;
  result.e164 = e164;
  result.e164Plus = '+' + e164;
  result.waLink = 'https://wa.me/' + e164;
  return result;
}

/**
 * Build a wa.me deep link. Returns null rather than a malformed URL when the
 * input cannot be normalized — callers must handle null (never interpolate
 * an unvalidated number straight into a URL).
 */
function buildWaLink(raw, opts) {
  const n = normalizePhone(raw, opts);
  return n.ok ? n.waLink : null;
}

/**
 * Convenience: strict variant that treats ambiguity as failure. Used on paths
 * where guessing wrong would message the wrong person (e.g. outbound sends).
 */
function normalizePhoneStrict(raw, opts) {
  const n = normalizePhone(raw, opts);
  if (n.ambiguous) {
    return Object.assign({}, n, { ok: false, e164: null, e164Plus: null, waLink: null });
  }
  return n;
}

// ----- scripts/lib/idempotency.js -----
/**
 * Idempotency and concurrency control.
 *
 * CANONICAL SOURCE. Unit-tested (tests/webhook/idempotency.test.js) and
 * injected into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * WHY THIS EXISTS
 * ---------------
 * Meta retries a webhook when it does not receive a timely 200. The same
 * message therefore arrives more than once, and a naive pipeline would create
 * duplicate Messages rows, duplicate Conversations, and — worst — assign the
 * same customer to two different agents and double-count both agents' load.
 *
 * The defence is layered:
 *   1. Deduplicate on the Meta message id (`wamid...`), which is globally
 *      unique and stable across retries. This is the primary guard and it is
 *      reliable.
 *   2. Serialize the assignment critical section. This is the WEAK guard,
 *      because Google Sheets offers no atomic compare-and-set. See
 *      docs/ASSIGNMENT_ALGORITHM.md for the honest limitations.
 */



/**
 * Build the deduplication key for an inbound event.
 *
 * For messages, the Meta message id alone is sufficient and correct.
 * For statuses, the same message id arrives repeatedly with DIFFERENT statuses
 * (sent -> delivered -> read), so the key must include the status, otherwise
 * legitimate status progression would be discarded as a duplicate.
 */
function buildDedupeKey(event) {
  const e = event || {};
  if (e.kind === 'status') {
    return 'status:' + String(e.message_id || 'unknown') + ':' + String(e.status || 'unknown');
  }
  if (e.kind === 'message') {
    return 'message:' + String(e.message_id || 'unknown');
  }
  // Unknown/error events: hash the stable identifying fields so repeated
  // deliveries of the same anomaly do not spam the audit log.
  const basis = JSON.stringify({
    kind: e.kind || null,
    waba: e.waba_id || null,
    biz: e.business_phone_number_id || null,
    code: e.error_code || null,
    reason: e.reason || null,
  });
  return 'other:' + crypto.createHash('sha256').update(basis).digest('hex').slice(0, 32);
}

/**
 * Decide whether an event has already been processed.
 *
 * @param {string} dedupeKey
 * @param {Array<object>} existingRows  Rows already in the Messages/Events
 *        sheet, each expected to expose `dedupe_key` (or `message_id`).
 * @returns {{ duplicate: boolean, matched: object|null }}
 */
function checkDuplicate(dedupeKey, existingRows) {
  const rows = Array.isArray(existingRows) ? existingRows : [];
  for (const row of rows) {
    if (!row) continue;
    const rowKey =
      row.dedupe_key !== undefined && row.dedupe_key !== null && String(row.dedupe_key) !== ''
        ? String(row.dedupe_key)
        : row.message_id !== undefined
          ? 'message:' + String(row.message_id)
          : null;
    if (rowKey !== null && rowKey === dedupeKey) {
      return { duplicate: true, matched: row };
    }
  }
  return { duplicate: false, matched: null };
}

/**
 * Detect an out-of-order status callback.
 *
 * Meta does not guarantee ordering, so `read` can arrive before `delivered`.
 * Statuses form a monotonic ladder; we must never downgrade a message that is
 * already READ back to DELIVERED.
 *
 * FAILED is terminal-but-special: it can legitimately follow SENT, and it must
 * never be overwritten by a late DELIVERED for the same message.
 */
const STATUS_RANK = {
  PENDING: 0,
  ACCEPTED: 1,
  SENT: 2,
  DELIVERED: 3,
  READ: 4,
  FAILED: 5,
};

function shouldApplyStatus(currentStatus, incomingStatus) {
  const cur = currentStatus ? String(currentStatus).toUpperCase() : null;
  const inc = incomingStatus ? String(incomingStatus).toUpperCase() : null;

  if (inc === null || STATUS_RANK[inc] === undefined) {
    return { apply: false, reason: 'UNKNOWN_INCOMING_STATUS' };
  }
  if (cur === null || STATUS_RANK[cur] === undefined) {
    return { apply: true, reason: 'NO_PRIOR_STATUS' };
  }
  if (cur === 'FAILED') {
    return { apply: false, reason: 'ALREADY_FAILED_TERMINAL' };
  }
  if (inc === 'FAILED') {
    return { apply: true, reason: 'FAILURE_OVERRIDES' };
  }
  if (STATUS_RANK[inc] > STATUS_RANK[cur]) {
    return { apply: true, reason: 'STATUS_ADVANCED' };
  }
  return { apply: false, reason: 'OUT_OF_ORDER_OR_STALE' };
}

/**
 * Advisory lock for the assignment critical section.
 *
 * HONEST LIMITATION: this is NOT a mutex. Google Sheets has no atomic
 * compare-and-set, so between "read lock row" and "write lock row" another
 * execution can interleave. What this buys us:
 *   - it collapses the race window from "the whole assignment pipeline"
 *     (several seconds of Sheets reads/writes) down to the round-trip of a
 *     single write (~200-400ms),
 *   - it makes contention VISIBLE in the audit log instead of silent,
 *   - it gives the eventual PostgreSQL implementation a drop-in seam: the same
 *     call site becomes `SELECT ... FOR UPDATE`.
